/**
 * THE AGENT TOOLS SOURCE OF THE INTERNAL API REFERENCE: what the Tracy agent (the dsh model) can call,
 * per kind of site, as one OpenAPI 3.1 document with no paths — the reference is its description.
 *
 * The data is `agent-tools.json`, GENERATED by `scripts/build-agent-tools.mjs` from the site-tools
 * plugin's own modules (this image cannot import `packages/`), and held to them by the `agent-tools`
 * gate. Nothing here restates a tool: every sentence about one comes from that file.
 */
import { readFileSync } from 'node:fs'

const DATA_URL = new URL('./agent-tools.json', import.meta.url)

/** @type {any} */
let cached = null

/** The generated catalogue, read once. */
export function agentToolsCatalogue() {
  cached ??= JSON.parse(readFileSync(DATA_URL, 'utf8'))
  return cached
}

const PLATFORM_NAMES = { joomla: 'Joomla', wordpress: 'WordPress', emdash: 'EmDash' }

/** Markdown-safe table cell. */
const cell = (value) =>
  String(value ?? '')
    .replace(/\|/g, '\\|')
    .replace(/\n/g, ' ')

const code = (value) => `\`${String(value)}\``

/** A fenced block longer than any backtick run inside it, so the text shows byte for byte. */
function fenced(text, lang = 'text') {
  const longest = Math.max(2, ...(String(text).match(/`+/g) ?? []).map((run) => run.length))
  const fence = '`'.repeat(longest + 1)
  return `${fence}${lang}\n${text}\n${fence}`
}

/** A collapsed block: a summary line, then the body. Blank lines keep the body Markdown. */
const collapsed = (summary, body) => `<details>\n<summary>${summary}</summary>\n\n${body}\n\n</details>`

const platforms = (list) =>
  Array.isArray(list) && list.length > 0 ? list.map((p) => PLATFORM_NAMES[p] ?? p).join(', ') : 'every site'

function doorCell(route) {
  if (route.door === 'apply') return `Apply door: ${code(route.applyAction)}`
  const via = [
    ...(route.applyActions ?? []).map((a) => `Apply door ${code(a)}`),
    ...(route.emdashTools ?? []).map((t) => `EmDash MCP ${code(t)}`)
  ]
  return via.length > 0 ? `Agent host itself, then ${via.join(', ')}` : 'Answered by the agent host itself'
}

function actionTable(actions) {
  return [
    '| Action | Tier | How it reaches the site | Notes |',
    '|---|---|---|---|',
    ...actions.map(
      (a) => `| ${code(a.action)} | ${cell(a.tier ?? '')} | ${cell(doorCell(a))} | ${cell(a.host ?? '')} |`
    )
  ].join('\n')
}

const schemaName = (surface) => `tracy_site.${surface}`

function siteSection(tool, surfaces) {
  const parts = [
    `## ${code(tool.name)}`,
    `The one door to the conversation's site (${cell(tool.plugin)}). The agent sends ${code('{action, params}')}; the ${code('action')} enum and the description depend on the site's surface, decided once when the agent is created and never changed mid-conversation.`,
    `Actions answered by the agent host itself: ${tool.localActions.map(code).join(', ')}. Every other action is relayed to the Apply door under the same name.`,
    'Tiers: `readonly` runs freely; `mutating` runs at once and can be undone; `destructive` answers `CONFIRM_FIRST` until the agent has asked the customer (`content.contract` is readonly for `inspect` and destructive for `multilingual.retire`).'
  ]
  for (const surface of surfaces) {
    const s = tool.surfaces[surface.id]
    if (!s) continue
    parts.push(
      `### ${code(tool.name)} on ${code(surface.id)}`,
      `${surface.meaning} ${s.actions.length} actions; parameters schema ${code(schemaName(surface.id))}.`,
      actionTable(s.actions),
      collapsed(
        `Description the model receives on ${surface.id} (${s.description.length} characters)`,
        fenced(s.description)
      )
    )
  }
  parts.push(
    `### ${code(tool.name)} fallback`,
    tool.fallback.when,
    collapsed(
      `Full description (${tool.fallback.description.length} characters)`,
      fenced(tool.fallback.description)
    )
  )
  return parts.join('\n\n')
}

function emdashSection(tool) {
  return [
    `## ${code(tool.name)}`,
    `${cell(tool.plugin)}, on ${platforms(tool.platforms)} sites only. ${tool.door} Tool names and arguments are EmDash's own; parameters schema ${code(tool.name)}.`,
    `Tools EmDash marks read-only (run in parallel): ${tool.readTools.map(code).join(', ')}.`,
    `Tools EmDash marks destructive (asked of the customer first): ${tool.destructiveTools.map(code).join(', ')}.`,
    collapsed(
      `Description the model receives (${tool.description.length} characters)`,
      fenced(tool.description)
    )
  ].join('\n\n')
}

function otherSection(tools) {
  const rows = tools.map(
    (t) => `| ${code(t.name)} | ${cell(t.plugin)} | ${cell(platforms(t.platforms))} | ${code(t.source)} |`
  )
  const texts = tools
    .filter((t) => typeof t.description === 'string')
    .map((t) => collapsed(`${t.name} (${t.description.length} characters)`, fenced(t.description)))
  const computed = tools.filter((t) => typeof t.description !== 'string').map((t) => code(t.name))
  return [
    '## Other Tracy tools',
    'Registered by the other plugins of the customer bundle. They do not reach the site through the Apply door; each runs in its own plugin. Found by reading their source, so only the name, owner and platforms are certain; a description is shown where the source gives it as plain text.',
    ['| Tool | Plugin | Sites | Source |', '|---|---|---|---|', ...rows].join('\n'),
    ...texts,
    ...(computed.length > 0
      ? [`Descriptions built at runtime, read them in the source: ${computed.join(', ')}.`]
      : [])
  ].join('\n\n')
}

/**
 * The Agent tools reference as an OpenAPI 3.1 document. No paths: the agent's tools are not HTTP
 * operations; the one HTTP door they reach is documented in the Internal API source.
 * @returns {Record<string, unknown>}
 */
export function buildAgentToolsOpenApi() {
  const data = agentToolsCatalogue()
  const site = data.tools.find((t) => t.name === 'tracy_site')
  const emdash = data.tools.find((t) => t.name === 'tracy_emdash')
  const surfaceRows = data.surfaces.map(
    (s) =>
      `| ${code(s.id)} | ${PLATFORM_NAMES[s.platform] ?? s.platform} | ${site?.surfaces[s.id]?.actions.length ?? 0} | ${cell(s.meaning)} |`
  )
  const overview = [
    'What the Tracy agent can call on a customer site: the tools, the actions each kind of site offers, the exact description text the model receives, and the door each call goes through.',
    `Generated from the site-tools plugin by ${code('scripts/build-agent-tools.mjs')}; the ${code('agent-tools')} gate fails when this copy drifts from the plugin.`,
    '## Surfaces',
    "A conversation belongs to one site. When the agent is created, the host reads the site's platform and seal and picks one surface; tools that act on another platform are hidden. When the platform or seal cannot be read, the agent keeps the full description (see the fallback below).",
    ['| Surface | Platform | `tracy_site` actions | Meaning |', '|---|---|---|---|', ...surfaceRows].join(
      '\n'
    ),
    '## How a call reaches a site',
    `1. The model calls a tool; the agent host (the dsh plugin) checks the action is on this surface, corrects its shape and names what it corrected in ${code('normalized')}.`,
    `2. A relayed ${code('tracy_site')} action is sent as ${code('{action, params, target?}')} to ${code(data.applyDoor)} with the viewer's session: the seat book checks the viewer's role and toolset, then the Claude Cowork plugin on the site runs it. The answer comes back verbatim, with a ${code('next')} on refusals.`,
    "3. A host action (page reads, screenshots, file searches, pictures, the replace job) runs in the agent host; any write it makes leaves through the Apply door, or on EmDash through the site's own MCP tools.",
    `4. ${code('tracy_emdash')} calls the EmDash site's own MCP server with the viewer's token; it never uses the Apply door.`,
    'The tool presets can hide further tools per role; this reference lists what the plugins register.'
  ]
  const description = [
    ...overview,
    ...(site ? [siteSection(site, data.surfaces)] : []),
    ...(emdash ? [emdashSection(emdash)] : []),
    otherSection(data.otherTools ?? [])
  ].join('\n\n')

  const schemas = {}
  for (const s of data.surfaces)
    if (site?.surfaces[s.id]) schemas[schemaName(s.id)] = site.surfaces[s.id].parameters
  if (emdash) schemas[emdash.name] = emdash.parameters

  return {
    openapi: '3.1.0',
    // No HTTP paths: a tool call reaches a site through the Apply door of the Tracy API.
    servers: [{ url: '/' }],
    security: [],
    info: { title: 'Tracy agent tools', version: data.schemaVersion, description },
    paths: {},
    components: { schemas }
  }
}
